insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900037', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'easy', 'published', 'Na base padrão $E=\{(1,0),(0,1)\}$ de $\mathbb R^2$, qual é o vetor de coordenadas de $v=(-2,5)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000371', '40000000-0000-4000-8000-000000900037', 'A', '$(-2,5)$', 1), ('50000000-0000-4000-8000-000009000372', '40000000-0000-4000-8000-000000900037', 'B', '$(5,-2)$', 2), ('50000000-0000-4000-8000-000009000373', '40000000-0000-4000-8000-000000900037', 'C', '$(2,-5)$', 3), ('50000000-0000-4000-8000-000009000374', '40000000-0000-4000-8000-000000900037', 'D', '$(-2,-5)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900037', '50000000-0000-4000-8000-000009000371') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900037', '30000000-0000-4000-8000-000000090011', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000371', '40000000-0000-4000-8000-000000900037', 'Na base padrão, os coeficientes coincidem com as componentes usuais.', 1), ('60000000-0000-4000-8000-000009000372', '40000000-0000-4000-8000-000000900037', 'Escreva $v=a(1,0)+b(0,1)$.', 2), ('60000000-0000-4000-8000-000009000373', '40000000-0000-4000-8000-000000900037', 'Confira primeiro a componente horizontal e depois a vertical.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900037', '$(-2,5)$', 'A base padrão isola cada eixo, portanto a primeira componente multiplica o primeiro vetor e a segunda multiplica o segundo. Não é necessário resolver um sistema adicional.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000371', '40000000-0000-4000-8000-000000900037', 'Expanda na base', '$v=a(1,0)+b(0,1)=(a,b)$.', 1), ('70000000-0000-4000-8000-000009000372', '40000000-0000-4000-8000-000000900037', 'Compare a primeira entrada', '$a=-2$.', 2), ('70000000-0000-4000-8000-000009000373', '40000000-0000-4000-8000-000000900037', 'Compare a segunda entrada', '$b=5$.', 3), ('70000000-0000-4000-8000-000009000374', '40000000-0000-4000-8000-000000900037', 'Registre as coordenadas', '$[v]_E=(-2,5)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900038', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'easy', 'published', 'Para a base $B=\{(1,1),(1,-1)\}$, determine $[(4,2)]_B$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000381', '40000000-0000-4000-8000-000000900038', 'A', '$(2,2)$', 1), ('50000000-0000-4000-8000-000009000382', '40000000-0000-4000-8000-000000900038', 'B', '$(3,1)$', 2), ('50000000-0000-4000-8000-000009000383', '40000000-0000-4000-8000-000000900038', 'C', '$(4,2)$', 3), ('50000000-0000-4000-8000-000009000384', '40000000-0000-4000-8000-000000900038', 'D', '$(1,3)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900038', '50000000-0000-4000-8000-000009000382') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900038', '30000000-0000-4000-8000-000000090011', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000381', '40000000-0000-4000-8000-000000900038', 'Procure $a$ e $b$ tais que $a(1,1)+b(1,-1)=(4,2)$.', 1), ('60000000-0000-4000-8000-000009000382', '40000000-0000-4000-8000-000000900038', 'Compare as duas componentes para obter um sistema.', 2), ('60000000-0000-4000-8000-000009000383', '40000000-0000-4000-8000-000000900038', 'Some as equações antes de isolar o segundo coeficiente.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900038', '$(3,1)$', 'Coordenadas relativas a uma base são os coeficientes da combinação dos vetores da base. Como a base não é a padrão, elas não precisam coincidir com as componentes usuais.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000381', '40000000-0000-4000-8000-000000900038', 'Monte o sistema', '$a+b=4$ e $a-b=2$.', 1), ('70000000-0000-4000-8000-000009000382', '40000000-0000-4000-8000-000000900038', 'Encontre $a$', 'Somando, $2a=6$, então $a=3$.', 2), ('70000000-0000-4000-8000-000009000383', '40000000-0000-4000-8000-000000900038', 'Encontre $b$', 'De $a+b=4$, resulta $b=1$.', 3), ('70000000-0000-4000-8000-000009000384', '40000000-0000-4000-8000-000000900038', 'Confira', '$3(1,1)+(1,-1)=(4,2)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900039', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'easy', 'published', 'Se $B=\{(1,0),(1,1)\}$ e $[v]_B=(2,-1)$, qual é $v$ na base padrão?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000391', '40000000-0000-4000-8000-000000900039', 'A', '$(3,1)$', 1), ('50000000-0000-4000-8000-000009000392', '40000000-0000-4000-8000-000000900039', 'B', '$(-1,2)$', 2), ('50000000-0000-4000-8000-000009000393', '40000000-0000-4000-8000-000000900039', 'C', '$(1,-1)$', 3), ('50000000-0000-4000-8000-000009000394', '40000000-0000-4000-8000-000000900039', 'D', '$(2,-1)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900039', '50000000-0000-4000-8000-000009000393') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900039', '30000000-0000-4000-8000-000000090011', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000391', '40000000-0000-4000-8000-000000900039', 'Use os números dados como coeficientes dos vetores de $B$.', 1), ('60000000-0000-4000-8000-000009000392', '40000000-0000-4000-8000-000000900039', 'Calcule $2(1,0)-(1,1)$.', 2), ('60000000-0000-4000-8000-000009000393', '40000000-0000-4000-8000-000000900039', 'Confira separadamente as duas componentes do resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900039', '$(1,-1)$', 'O vetor de coordenadas registra pesos relativos à base indicada. Para recuperar o vetor geométrico, multiplicamos cada vetor da base por seu coeficiente e somamos.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000391', '40000000-0000-4000-8000-000000900039', 'Interprete a notação', '$v=2b_1-1b_2$.', 1), ('70000000-0000-4000-8000-000009000392', '40000000-0000-4000-8000-000000900039', 'Substitua a base', '$v=2(1,0)-(1,1)$.', 2), ('70000000-0000-4000-8000-000009000393', '40000000-0000-4000-8000-000000900039', 'Some componentes', '$v=(2,0)+(-1,-1)=(1,-1)$.', 3), ('70000000-0000-4000-8000-000009000394', '40000000-0000-4000-8000-000000900039', 'Diferencie as representações', 'O par $(2,-1)$ são coordenadas em $B$; o vetor padrão é $(1,-1)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900040', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'easy', 'published', 'Para $B=\{(2,1),(0,3)\}$, qual matriz converte $[v]_B$ em coordenadas padrão?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000401', '40000000-0000-4000-8000-000000900040', 'A', '$\begin{pmatrix}2&1\\0&3\end{pmatrix}$', 1), ('50000000-0000-4000-8000-000009000402', '40000000-0000-4000-8000-000000900040', 'B', '$\begin{pmatrix}1/2&0\\-1/6&1/3\end{pmatrix}$', 2), ('50000000-0000-4000-8000-000009000403', '40000000-0000-4000-8000-000000900040', 'C', '$\begin{pmatrix}2&0\\3&1\end{pmatrix}$', 3), ('50000000-0000-4000-8000-000009000404', '40000000-0000-4000-8000-000000900040', 'D', '$\begin{pmatrix}2&0\\1&3\end{pmatrix}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900040', '50000000-0000-4000-8000-000009000404') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900040', '30000000-0000-4000-8000-000000090012', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000401', '40000000-0000-4000-8000-000000900040', 'A imagem de cada vetor coordenado padrão deve ser o vetor correspondente de $B$.', 1), ('60000000-0000-4000-8000-000009000402', '40000000-0000-4000-8000-000000900040', 'As colunas da matriz são os vetores da base escritos na base de chegada.', 2), ('60000000-0000-4000-8000-000009000403', '40000000-0000-4000-8000-000000900040', 'Preserve a ordem dos vetores em $B$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900040', '$\begin{pmatrix}2&0\\1&3\end{pmatrix}$', 'A matriz de coordenadas de $B$ para a base padrão é formada colocando os vetores de $B$ como colunas. Multiplicá-la pelos coeficientes reproduz a combinação linear original.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000401', '40000000-0000-4000-8000-000000900040', 'Use a primeira coluna', 'Ela deve ser o vetor $(2,1)$.', 1), ('70000000-0000-4000-8000-000009000402', '40000000-0000-4000-8000-000000900040', 'Use a segunda coluna', 'Ela deve ser o vetor $(0,3)$.', 2), ('70000000-0000-4000-8000-000009000403', '40000000-0000-4000-8000-000000900040', 'Monte a matriz', '$P_{E\leftarrow B}=\begin{pmatrix}2&0\\1&3\end{pmatrix}$.', 3), ('70000000-0000-4000-8000-000009000404', '40000000-0000-4000-8000-000000900040', 'Confira', '$P_{Eleftarrow B}(a,b)=a(2,1)+b(0,3)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900041', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'easy', 'published', 'Na base ordenada $B=(1,x,x^2)$ de $P_2$, quais são as coordenadas de $p(x)=2-x+3x^2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000411', '40000000-0000-4000-8000-000000900041', 'A', '$(2,-1,3)$', 1), ('50000000-0000-4000-8000-000009000412', '40000000-0000-4000-8000-000000900041', 'B', '$(3,-1,2)$', 2), ('50000000-0000-4000-8000-000009000413', '40000000-0000-4000-8000-000000900041', 'C', '$(2,1,3)$', 3), ('50000000-0000-4000-8000-000009000414', '40000000-0000-4000-8000-000000900041', 'D', '$(-1,2,3)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900041', '50000000-0000-4000-8000-000009000411') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900041', '30000000-0000-4000-8000-000000090011', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000411', '40000000-0000-4000-8000-000000900041', 'A ordem da base determina a ordem das coordenadas.', 1), ('60000000-0000-4000-8000-000009000412', '40000000-0000-4000-8000-000000900041', 'Leia primeiro o termo constante.', 2), ('60000000-0000-4000-8000-000009000413', '40000000-0000-4000-8000-000000900041', 'O coeficiente de $x$ inclui seu sinal.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900041', '$(2,-1,3)$', 'Na base monomial ordenada do termo constante ao quadrático, as coordenadas são exatamente os coeficientes nessa mesma ordem. Inverter a ordem ou perder o sinal muda a representação.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000411', '40000000-0000-4000-8000-000000900041', 'Separe os termos', '$p=2\cdot1+(-1)\cdot x+3\cdot x^2$.', 1), ('70000000-0000-4000-8000-000009000412', '40000000-0000-4000-8000-000000900041', 'Associe à base', 'Os pesos de $(1,x,x^2)$ são $2,-1,3$.', 2), ('70000000-0000-4000-8000-000009000413', '40000000-0000-4000-8000-000000900041', 'Respeite a ordem', 'A primeira coordenada é a constante, não o coeficiente líder.', 3), ('70000000-0000-4000-8000-000009000414', '40000000-0000-4000-8000-000000900041', 'Conclua', '$[p]_B=(2,-1,3)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900042', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'easy', 'published', 'Considere $\mathbb R^2=U\oplus V$, com $U=\operatorname{span}\{(1,0)\}$ e $V=\operatorname{span}\{(0,1)\}$. Qual é a decomposição de $(3,-2)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000421', '40000000-0000-4000-8000-000000900042', 'A', '$(1,0)+(0,1)$', 1), ('50000000-0000-4000-8000-000009000422', '40000000-0000-4000-8000-000000900042', 'B', '$(3,0)+(0,-2)$', 2), ('50000000-0000-4000-8000-000009000423', '40000000-0000-4000-8000-000000900042', 'C', '$(0,3)+(-2,0)$', 3), ('50000000-0000-4000-8000-000009000424', '40000000-0000-4000-8000-000000900042', 'D', '$(3,-2)+(0,0)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900042', '50000000-0000-4000-8000-000009000422') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900042', '30000000-0000-4000-8000-000000090013', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000421', '40000000-0000-4000-8000-000000900042', 'A parcela em $U$ deve ter segunda componente zero.', 1), ('60000000-0000-4000-8000-000009000422', '40000000-0000-4000-8000-000000900042', 'A parcela em $V$ deve ter primeira componente zero.', 2), ('60000000-0000-4000-8000-000009000423', '40000000-0000-4000-8000-000000900042', 'As duas parcelas precisam somar o vetor original.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900042', '$(3,0)+(0,-2)$', 'Na soma direta dos eixos coordenados, cada componente pertence a um dos subespaços. A decomposição é única porque os eixos só se intersectam no vetor zero.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000421', '40000000-0000-4000-8000-000000900042', 'Projete em $U$', 'A componente horizontal de $(3,-2)$ fornece $(3,0)$.', 1), ('70000000-0000-4000-8000-000009000422', '40000000-0000-4000-8000-000000900042', 'Projete em $V$', 'A componente vertical fornece $(0,-2)$.', 2), ('70000000-0000-4000-8000-000009000423', '40000000-0000-4000-8000-000000900042', 'Some', '$(3,0)+(0,-2)=(3,-2)$.', 3), ('70000000-0000-4000-8000-000009000424', '40000000-0000-4000-8000-000000900042', 'Confira a unicidade', '$Ucap V={0}$, então não há outra decomposição.', 4)
