insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000431', '40000000-0000-4000-8000-000000900043', 'A', '$(2,3)$', 1), ('50000000-0000-4000-8000-000009000432', '40000000-0000-4000-8000-000000900043', 'B', '$(1,5)$', 2), ('50000000-0000-4000-8000-000009000433', '40000000-0000-4000-8000-000000900043', 'C', '$(5,-1)$', 3), ('50000000-0000-4000-8000-000009000434', '40000000-0000-4000-8000-000000900043', 'D', '$(-1,5)$', 4)
