insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000431', '40000000-0000-4000-8000-000000900043', 'As coordenadas em $B$ são coeficientes dos dois vetores da base.', 1), ('60000000-0000-4000-8000-000009000432', '40000000-0000-4000-8000-000000900043', 'Calcule $2b_1+3b_2$.', 2), ('60000000-0000-4000-8000-000009000433', '40000000-0000-4000-8000-000000900043', 'Confira o sinal da segunda componente de $b_2$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900043', '$(5,-1)$', 'Converter da base $B$ para a padrão significa reconstruir o vetor pela combinação linear. A matriz cujas colunas são os vetores de $B$ multiplica o vetor de coordenadas.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000431', '40000000-0000-4000-8000-000000900043', 'Escreva a combinação', '$v=2(1,1)+3(1,-1)$.', 1), ('70000000-0000-4000-8000-000009000432', '40000000-0000-4000-8000-000000900043', 'Calcule as parcelas', '$2b_1=(2,2)$ e $3b_2=(3,-3)$.', 2), ('70000000-0000-4000-8000-000009000433', '40000000-0000-4000-8000-000000900043', 'Some', '$v=(5,-1)$.', 3), ('70000000-0000-4000-8000-000009000434', '40000000-0000-4000-8000-000000900043', 'Confira por matriz', '$\begin{pmatrix}1&1\\1&-1\end{pmatrix}(2,3)=(5,-1)$.', 4)
