insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000441', '40000000-0000-4000-8000-000000900044', 'Dois vetores em $\mathbb R^2$ formam base quando o determinante é não nulo.', 1), ('60000000-0000-4000-8000-000009000442', '40000000-0000-4000-8000-000000900044', 'Use os vetores como colunas.', 2), ('60000000-0000-4000-8000-000009000443', '40000000-0000-4000-8000-000000900044', 'Fatore $1-a^2$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900044', '$a
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000441', '40000000-0000-4000-8000-000000900044', 'Monte a matriz', '$P=\begin{pmatrix}1&a\\a&1\end{pmatrix}$.', 1), ('70000000-0000-4000-8000-000009000442', '40000000-0000-4000-8000-000000900044', 'Calcule o determinante', '$\det P=1-a^2$.', 2), ('70000000-0000-4000-8000-000009000443', '40000000-0000-4000-8000-000000900044', 'Encontre os zeros', '$1-a^2=(1-a)(1+a)=0$ em $a=\pm1$.', 3), ('70000000-0000-4000-8000-000009000444', '40000000-0000-4000-8000-000000900044', 'Conclua', 'Fora desses valores, o determinante é não nulo e $B_a$ é base.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900045', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'medium', 'published', 'Se $B=\{(2,0),(1,1)\}$, determine $[(1,2)]_B$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000451', '40000000-0000-4000-8000-000000900045', 'A', '$(-1/2,2)$', 1), ('50000000-0000-4000-8000-000009000452', '40000000-0000-4000-8000-000000900045', 'B', '$(1/2,2)$', 2), ('50000000-0000-4000-8000-000009000453', '40000000-0000-4000-8000-000000900045', 'C', '$(1,2)$', 3), ('50000000-0000-4000-8000-000009000454', '40000000-0000-4000-8000-000000900045', 'D', '$(2,-1/2)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900045', '50000000-0000-4000-8000-000009000451') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900045', '30000000-0000-4000-8000-000000090011', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000451', '40000000-0000-4000-8000-000000900045', 'Escreva $a(2,0)+b(1,1)=(1,2)$.', 1), ('60000000-0000-4000-8000-000009000452', '40000000-0000-4000-8000-000000900045', 'A segunda componente determina $b$ imediatamente.', 2), ('60000000-0000-4000-8000-000009000453', '40000000-0000-4000-8000-000000900045', 'Substitua esse valor na primeira componente.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900045', '$(-1/2,2)$', 'A base é triangular: a segunda coordenada do vetor determina diretamente o segundo coeficiente. O primeiro coeficiente surge depois de compensar a contribuição desse vetor na primeira entrada.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000451', '40000000-0000-4000-8000-000000900045', 'Compare a segunda entrada', '$b=2$.', 1), ('70000000-0000-4000-8000-000009000452', '40000000-0000-4000-8000-000000900045', 'Compare a primeira', '$2a+b=1$.', 2), ('70000000-0000-4000-8000-000009000453', '40000000-0000-4000-8000-000000900045', 'Substitua', '$2a+2=1$, então $a=-1/2$.', 3), ('70000000-0000-4000-8000-000009000454', '40000000-0000-4000-8000-000000900045', 'Confira', '$(-1/2)(2,0)+2(1,1)=(-1,0)+(2,2)=(1,2)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900046', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'medium', 'published', 'Em $P_1$, use a base $B=\{1+x,1-x\}$. Qual é $[4+2x]_B$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000461', '40000000-0000-4000-8000-000000900046', 'A', '$(2,2)$', 1), ('50000000-0000-4000-8000-000009000462', '40000000-0000-4000-8000-000000900046', 'B', '$(3,1)$', 2), ('50000000-0000-4000-8000-000009000463', '40000000-0000-4000-8000-000000900046', 'C', '$(1,3)$', 3), ('50000000-0000-4000-8000-000009000464', '40000000-0000-4000-8000-000000900046', 'D', '$(4,2)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900046', '50000000-0000-4000-8000-000009000462') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900046', '30000000-0000-4000-8000-000000090011', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000461', '40000000-0000-4000-8000-000000900046', 'Procure $a(1+x)+b(1-x)=4+2x$.', 1), ('60000000-0000-4000-8000-000009000462', '40000000-0000-4000-8000-000000900046', 'Compare o termo constante e o coeficiente de $x$.', 2), ('60000000-0000-4000-8000-000009000463', '40000000-0000-4000-8000-000000900046', 'O sistema resultante tem soma $a+b$ e diferença $a-b$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900046', '$(3,1)$', 'A igualdade de polinômios exige igualdade de cada coeficiente. A base escolhida mistura os termos constante e linear, por isso resolvemos um sistema para encontrar os pesos.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000461', '40000000-0000-4000-8000-000000900046', 'Expanda a combinação', '$a(1+x)+b(1-x)=(a+b)+(a-b)x$.', 1), ('70000000-0000-4000-8000-000009000462', '40000000-0000-4000-8000-000000900046', 'Compare coeficientes', '$a+b=4$ e $a-b=2$.', 2), ('70000000-0000-4000-8000-000009000463', '40000000-0000-4000-8000-000000900046', 'Resolva', 'Somando, $2a=6$, então $a=3$ e $b=1$.', 3), ('70000000-0000-4000-8000-000009000464', '40000000-0000-4000-8000-000000900046', 'Verifique', '$3(1+x)+(1-x)=4+2x$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900047', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'medium', 'published', 'Em $M_{2\times2}$, considere a base ordenada $B=(E_{11},E_{21},E_{12},E_{22})$. Quais são as coordenadas de $A=\begin{pmatrix}2&-1\\3&4\end{pmatrix}$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000471', '40000000-0000-4000-8000-000000900047', 'A', '$(4,3,-1,2)$', 1), ('50000000-0000-4000-8000-000009000472', '40000000-0000-4000-8000-000000900047', 'B', '$(2,3,4,-1)$', 2), ('50000000-0000-4000-8000-000009000473', '40000000-0000-4000-8000-000000900047', 'C', '$(2,3,-1,4)$', 3), ('50000000-0000-4000-8000-000009000474', '40000000-0000-4000-8000-000000900047', 'D', '$(2,-1,3,4)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900047', '50000000-0000-4000-8000-000009000473') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900047', '30000000-0000-4000-8000-000000090011', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000471', '40000000-0000-4000-8000-000000900047', 'Siga a ordem da base, que não é a ordem usual de leitura por linhas.', 1), ('60000000-0000-4000-8000-000009000472', '40000000-0000-4000-8000-000000900047', '$E_{21}$ registra a entrada inferior esquerda.', 2), ('60000000-0000-4000-8000-000009000473', '40000000-0000-4000-8000-000000900047', 'Associe uma coordenada a cada matriz unitária.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900047', '$(2,3,-1,4)$', 'As coordenadas dependem da ordem declarada. Nesta base, as duas primeiras posições percorrem a primeira coluna e as duas últimas percorrem a segunda coluna.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000471', '40000000-0000-4000-8000-000000900047', 'Expanda pela base', '$A=2E_{11}+3E_{21}-E_{12}+4E_{22}$.', 1), ('70000000-0000-4000-8000-000009000472', '40000000-0000-4000-8000-000000900047', 'Leia os dois primeiros pesos', 'Para $E_{11},E_{21}$, os coeficientes são $2,3$.', 2), ('70000000-0000-4000-8000-000009000473', '40000000-0000-4000-8000-000000900047', 'Leia os restantes', 'Para $E_{12},E_{22}$, são $-1,4$.', 3), ('70000000-0000-4000-8000-000009000474', '40000000-0000-4000-8000-000000900047', 'Conclua', '$[A]_B=(2,3,-1,4)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900048', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'medium', 'published', 'A matriz $P_{E\leftarrow B}$ de uma base ordenada de $\mathbb R^2$ tem determinante $-3$. O que o sinal negativo informa?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000481', '40000000-0000-4000-8000-000000900048', 'A', 'Os vetores de $B$ são dependentes.', 1), ('50000000-0000-4000-8000-000009000482', '40000000-0000-4000-8000-000000900048', 'B', 'A área do paralelogramo é negativa.', 2), ('50000000-0000-4000-8000-000009000483', '40000000-0000-4000-8000-000000900048', 'C', 'A mudança de base não é invertível.', 3), ('50000000-0000-4000-8000-000009000484', '40000000-0000-4000-8000-000000900048', 'D', 'A orientação de $B$ é oposta à da base padrão.', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900048', '50000000-0000-4000-8000-000009000484') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900048', '30000000-0000-4000-8000-000000090012', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000481', '40000000-0000-4000-8000-000000900048', 'Determinante não nulo já garante que há uma base.', 1), ('60000000-0000-4000-8000-000009000482', '40000000-0000-4000-8000-000000900048', 'O módulo mede o fator de área.', 2), ('60000000-0000-4000-8000-000009000483', '40000000-0000-4000-8000-000000900048', 'O sinal registra preservação ou reversão de orientação.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900048', 'A orientação de $B$ é oposta à da base padrão.', 'O módulo três indica o fator de escala de área, sempre interpretado como positivo. O sinal negativo não destrói a invertibilidade; ele registra uma reversão de orientação.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000481', '40000000-0000-4000-8000-000000900048', 'Use o módulo', '$|\det P|=3$ é o fator de área.', 1), ('70000000-0000-4000-8000-000009000482', '40000000-0000-4000-8000-000000900048', 'Use o sinal', '$\det P<0$ indica inversão da orientação ordenada.', 2), ('70000000-0000-4000-8000-000009000483', '40000000-0000-4000-8000-000000900048', 'Exclua dependência', 'Como o determinante não é zero, as colunas são independentes.', 3), ('70000000-0000-4000-8000-000009000484', '40000000-0000-4000-8000-000000900048', 'Conclua', 'A base existe, mas sua orientação é oposta à padrão.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900049', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'hard', 'published', 'Se $B=\{(1,1),(1,0)\}$ e $C=\{(1,0),(1,1)\}$, qual matriz transforma $[v]_B$ em $[v]_C$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000491', '40000000-0000-4000-8000-000000900049', 'A', '$\begin{pmatrix}0&1\\1&0\end{pmatrix}$', 1), ('50000000-0000-4000-8000-000009000492', '40000000-0000-4000-8000-000000900049', 'B', '$\begin{pmatrix}1&1\\1&0\end{pmatrix}$', 2), ('50000000-0000-4000-8000-000009000493', '40000000-0000-4000-8000-000000900049', 'C', '$\begin{pmatrix}0&1\\1&-1\end{pmatrix}$', 3), ('50000000-0000-4000-8000-000009000494', '40000000-0000-4000-8000-000000900049', 'D', '$\begin{pmatrix}1&0\\0&1\end{pmatrix}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900049', '50000000-0000-4000-8000-000009000491') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900049', '30000000-0000-4000-8000-000000090012', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000491', '40000000-0000-4000-8000-000000900049', 'Cada coluna é a coordenada de um vetor de $B$ na base $C$.', 1), ('60000000-0000-4000-8000-000009000492', '40000000-0000-4000-8000-000000900049', 'Escreva primeiro $(1,1)$ como combinação dos vetores de $C$.', 2), ('60000000-0000-4000-8000-000009000493', '40000000-0000-4000-8000-000000900049', 'Repita para $(1,0)$ e preserve a ordem.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900049', '$\begin{pmatrix}0&1\\1&0\end{pmatrix}$', 'A matriz de transição $Cleftarrow B$ recebe coeficientes na base $B$. Por isso suas colunas são as coordenadas, em $C$, dos vetores da base de partida.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000491', '40000000-0000-4000-8000-000000900049', 'Converta $b_1$', '$(1,1)=0(1,0)+1(1,1)$, então $[b_1]_C=(0,1)$.', 1), ('70000000-0000-4000-8000-000009000492', '40000000-0000-4000-8000-000000900049', 'Converta $b_2$', '$(1,0)=1(1,0)+0(1,1)$, então $[b_2]_C=(1,0)$.', 2), ('70000000-0000-4000-8000-000009000493', '40000000-0000-4000-8000-000000900049', 'Monte pelas colunas', '$P_{C\leftarrow B}=\begin{pmatrix}0&1\\1&0\end{pmatrix}$.', 3), ('70000000-0000-4000-8000-000009000494', '40000000-0000-4000-8000-000000900049', 'Confira', 'A matriz troca as duas coordenadas, coerente com a troca de ordem entre as bases.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900050', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'hard', 'published', 'São conhecidas $P_{C\leftarrow B}$ e $P_{D\leftarrow C}$. Qual expressão converte diretamente $[v]_B$ em $[v]_D$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000501', '40000000-0000-4000-8000-000000900050', 'A', '$P_{C\leftarrow B}^{-1}P_{D\leftarrow C}$', 1), ('50000000-0000-4000-8000-000009000502', '40000000-0000-4000-8000-000000900050', 'B', '$P_{D\leftarrow C}P_{C\leftarrow B}$', 2), ('50000000-0000-4000-8000-000009000503', '40000000-0000-4000-8000-000000900050', 'C', '$P_{C\leftarrow B}P_{D\leftarrow C}$', 3), ('50000000-0000-4000-8000-000009000504', '40000000-0000-4000-8000-000000900050', 'D', '$P_{D\leftarrow C}+P_{C\leftarrow B}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900050', '50000000-0000-4000-8000-000009000502') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900050', '30000000-0000-4000-8000-000000090012', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000501', '40000000-0000-4000-8000-000000900050', 'Aplique primeiro a conversão de $B$ para $C$.', 1), ('60000000-0000-4000-8000-000009000502', '40000000-0000-4000-8000-000000900050', 'A transformação aplicada primeiro aparece à direita no produto.', 2), ('60000000-0000-4000-8000-000009000503', '40000000-0000-4000-8000-000000900050', 'A saída intermediária em $C$ deve ser a entrada da segunda matriz.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900050', '$P_{D\leftarrow C}P_{C\leftarrow B}$', 'A composição segue o fluxo das coordenadas: $B$ para $C$ e depois $C$ para $D$. Na notação matricial, a primeira ação fica à direita, garantindo compatibilidade entre os espaços intermediários.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000501', '40000000-0000-4000-8000-000000900050', 'Faça a primeira conversão', '$[v]_C=P_{Cleftarrow B}[v]_B$.', 1), ('70000000-0000-4000-8000-000009000502', '40000000-0000-4000-8000-000000900050', 'Faça a segunda', '$[v]_D=P_{Dleftarrow C}[v]_C$.', 2), ('70000000-0000-4000-8000-000009000503', '40000000-0000-4000-8000-000000900050', 'Substitua a expressão', '$[v]_D=P_{Dleftarrow C}P_{Cleftarrow B}[v]_B$.', 3), ('70000000-0000-4000-8000-000009000504', '40000000-0000-4000-8000-000000900050', 'Leia a matriz direta', 'O produto na ordem indicada é $P_{Dleftarrow B}$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900051', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'hard', 'published', 'Na base $B=(1,x-1,(x-1)^2)$ de $P_2$, quais são as coordenadas de $x^2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000511', '40000000-0000-4000-8000-000000900051', 'A', '$(1,-2,1)$', 1), ('50000000-0000-4000-8000-000009000512', '40000000-0000-4000-8000-000000900051', 'B', '$(1,1,2)$', 2), ('50000000-0000-4000-8000-000009000513', '40000000-0000-4000-8000-000000900051', 'C', '$(1,2,1)$', 3), ('50000000-0000-4000-8000-000009000514', '40000000-0000-4000-8000-000000900051', 'D', '$(0,0,1)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900051', '50000000-0000-4000-8000-000009000513') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900051', '30000000-0000-4000-8000-000000090011', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000511', '40000000-0000-4000-8000-000000900051', 'Defina $y=x-1$, de modo que $x=y+1$.', 1), ('60000000-0000-4000-8000-000009000512', '40000000-0000-4000-8000-000000900051', 'Reescreva $x^2$ em potências de $y$.', 2), ('60000000-0000-4000-8000-000009000513', '40000000-0000-4000-8000-000000900051', 'Associe os coeficientes a $1,y,y^2$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900051', '$(1,2,1)$', 'A base é centrada em $x=1$, então os coeficientes devem ser obtidos em potências de $x-1$. Uma substituição simples evita expandir combinações desconhecidas.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000511', '40000000-0000-4000-8000-000000900051', 'Troque a variável', 'Se $y=x-1$, então $x=y+1$.', 1), ('70000000-0000-4000-8000-000009000512', '40000000-0000-4000-8000-000000900051', 'Eleve ao quadrado', '$x^2=(y+1)^2=1+2y+y^2$.', 2), ('70000000-0000-4000-8000-000009000513', '40000000-0000-4000-8000-000000900051', 'Retorne à base', '$x^2=1+2(x-1)+(x-1)^2$.', 3), ('70000000-0000-4000-8000-000009000514', '40000000-0000-4000-8000-000000900051', 'Leia as coordenadas', 'Os coeficientes são $(1,2,1)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900052', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'hard', 'published', 'Uma base ordenada de $\mathbb R^2$ é $B=(b_1,b_2)$, com $b_1=(1,2)$. Sabe-se que $[(5,1)]_B=(2,-1)$. Qual é $b_2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000521', '40000000-0000-4000-8000-000000900052', 'A', '$(3,-3)$', 1), ('50000000-0000-4000-8000-000009000522', '40000000-0000-4000-8000-000000900052', 'B', '$(7,5)$', 2), ('50000000-0000-4000-8000-000009000523', '40000000-0000-4000-8000-000000900052', 'C', '$(-1,2)$', 3), ('50000000-0000-4000-8000-000009000524', '40000000-0000-4000-8000-000000900052', 'D', '$(-3,3)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900052', '50000000-0000-4000-8000-000009000524') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900052', '30000000-0000-4000-8000-000000090011', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000521', '40000000-0000-4000-8000-000000900052', 'Traduza as coordenadas como uma combinação $2b_1-b_2$.', 1), ('60000000-0000-4000-8000-000009000522', '40000000-0000-4000-8000-000000900052', 'Substitua o vetor conhecido $b_1$.', 2), ('60000000-0000-4000-8000-000009000523', '40000000-0000-4000-8000-000000900052', 'Isole $b_2$ na igualdade vetorial.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900052', '$(-3,3)$', 'O dado coordenado fornece uma equação vetorial capaz de determinar o segundo vetor da base. É preciso respeitar o coeficiente negativo associado a $b_2$ ao isolá-lo.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000521', '40000000-0000-4000-8000-000000900052', 'Traduza o dado', '$(5,1)=2b_1-b_2$.', 1), ('70000000-0000-4000-8000-000009000522', '40000000-0000-4000-8000-000000900052', 'Substitua $b_1$', '$(5,1)=(2,4)-b_2$.', 2), ('70000000-0000-4000-8000-000009000523', '40000000-0000-4000-8000-000000900052', 'Isole o vetor', '$b_2=(2,4)-(5,1)=(-3,3)$.', 3), ('70000000-0000-4000-8000-000009000524', '40000000-0000-4000-8000-000000900052', 'Confira a base', '$b_1$ e $b_2$ não são proporcionais e $2b_1-b_2=(5,1)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900053', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'hard', 'published', 'Considere $\mathbb R^2=U\oplus V$, onde $U=\operatorname{span}\{(1,0)\}$ e $V=\operatorname{span}\{(1,1)\}$. A projeção sobre $U$ ao longo de $V$ envia $(3,2)$ em qual vetor?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000531', '40000000-0000-4000-8000-000000900053', 'A', '$(1,0)$', 1), ('50000000-0000-4000-8000-000009000532', '40000000-0000-4000-8000-000000900053', 'B', '$(3,0)$', 2), ('50000000-0000-4000-8000-000009000533', '40000000-0000-4000-8000-000000900053', 'C', '$(2,2)$', 3), ('50000000-0000-4000-8000-000009000534', '40000000-0000-4000-8000-000000900053', 'D', '$(0,2)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900053', '50000000-0000-4000-8000-000009000531') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900053', '30000000-0000-4000-8000-000000090013', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000531', '40000000-0000-4000-8000-000000900053', 'Decomponha $(3,2)=u+v$ com $uin U$ e $vin V$.', 1), ('60000000-0000-4000-8000-000009000532', '40000000-0000-4000-8000-000000900053', 'Escreva $u=(a,0)$ e $v=(b,b)$.', 2), ('60000000-0000-4000-8000-000009000533', '40000000-0000-4000-8000-000000900053', 'A projeção pedida mantém apenas a parcela em $U$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900053', '$(1,0)$', 'A projeção ao longo de $V$ usa a decomposição direta definida pelos dois subespaços, não a perpendicularidade. O vetor é separado em uma parcela horizontal e outra na direção $(1,1)$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000531', '40000000-0000-4000-8000-000000900053', 'Parametrize as parcelas', '$(3,2)=(a,0)+(b,b)=(a+b,b)$.', 1), ('70000000-0000-4000-8000-000009000532', '40000000-0000-4000-8000-000000900053', 'Compare a segunda entrada', '$b=2$.', 2), ('70000000-0000-4000-8000-000009000533', '40000000-0000-4000-8000-000000900053', 'Encontre a parcela em $U$', '$a+b=3$ dá $a=1$.', 3), ('70000000-0000-4000-8000-000009000534', '40000000-0000-4000-8000-000000900053', 'Aplique a projeção', 'A parcela preservada é $u=(1,0)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900054', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090003', 'multiple_choice', 'hard', 'published', 'No plano $W=\{(x,y,z):x+y+z=0\}$, use a base $B=\{(1,-1,0),(1,0,-1)\}$. Qual é $[(3,-1,-2)]_B$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000541', '40000000-0000-4000-8000-000000900054', 'A', '$(1,2,0)$', 1), ('50000000-0000-4000-8000-000009000542', '40000000-0000-4000-8000-000000900054', 'B', '$(1,2)$', 2), ('50000000-0000-4000-8000-000009000543', '40000000-0000-4000-8000-000000900054', 'C', '$(2,1)$', 3), ('50000000-0000-4000-8000-000009000544', '40000000-0000-4000-8000-000000900054', 'D', '$(3,-1)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900054', '50000000-0000-4000-8000-000009000542') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900054', '30000000-0000-4000-8000-000000090011', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000541', '40000000-0000-4000-8000-000000900054', 'Primeiro confira que o vetor pertence a $W$.', 1), ('60000000-0000-4000-8000-000009000542', '40000000-0000-4000-8000-000000900054', 'Escreva $a(1,-1,0)+b(1,0,-1)=(3,-1,-2)$.', 2), ('60000000-0000-4000-8000-000009000543', '40000000-0000-4000-8000-000000900054', 'As componentes $y$ e $z$ determinam diretamente $a$ e $b$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900054', '$(1,2)$', 'Embora $W$ esteja dentro de $\mathbb R^3$, sua base tem dois vetores e as coordenadas relativas a ela têm apenas duas entradas. As componentes ambiente determinam esses dois pesos.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000541', '40000000-0000-4000-8000-000000900054', 'Confira a pertinência', '$3-1-2=0$, então o vetor está em $W$.', 1), ('70000000-0000-4000-8000-000009000542', '40000000-0000-4000-8000-000000900054', 'Compare a componente $y$', '$-a=-1$, logo $a=1$.', 2), ('70000000-0000-4000-8000-000009000543', '40000000-0000-4000-8000-000000900054', 'Compare a componente $z$', '$-b=-2$, logo $b=2$.', 3), ('70000000-0000-4000-8000-000009000544', '40000000-0000-4000-8000-000000900054', 'Verifique a componente $x$', '$a+b=1+2=3$, confirmando $[v]_B=(1,2)$.', 4)
